
public class ConcatenacionStrings {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		double salario = 1850.55;
		
		double salarioEnDolares = salario*1.12;
		
		System.out.println("El Salario de Manuel es " + salario+ "eur, a dia de hoy\n");
		System.out.println("El Salario en Dolares de Manuel es " + salarioEnDolares);

	}

}
